param()
$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot
$container='salesflow-sp3t6-'+[guid]::NewGuid().ToString('N')
$launched=$false;$jobs=@()
function Query([string]$sql){$prior=$ErrorActionPreference;$ErrorActionPreference='Continue';$out=@($sql|docker exec -i -e PGOPTIONS=-cclient_min_messages=error $container psql -U postgres -v ON_ERROR_STOP=1 -qAt 2>&1|ForEach-Object{$_.ToString()});$code=$LASTEXITCODE;$ErrorActionPreference=$prior;if($code-ne0){throw "SP3-T6 SQL failed: $($out-join[Environment]::NewLine)"};$out}
function Check($condition,[string]$label){if(-not$condition){throw "SP3-T6 $label"};Write-Host "PASS SP3-T6 $label"}
try{
 $manifest=Get-Content (Join-Path $root 'release/release-manifest.json') -Raw|ConvertFrom-Json;$image=[string]$manifest.images[0];Check ($image-match'^postgres@sha256:[a-f0-9]{64}$') 'pinned PostgreSQL image'
 $password=[guid]::NewGuid().ToString('N');docker run --detach --rm --name $container --network none -e "POSTGRES_PASSWORD=$password" $image *> $null;Check ($LASTEXITCODE-eq0) 'disposable PostgreSQL started';$launched=$true
 $ready=$false;for($n=0;$n-lt60;$n++){docker exec $container pg_isready -U postgres *> $null;if($LASTEXITCODE-eq0){$ready=$true;break};Start-Sleep -Milliseconds 250};Check $ready 'database ready'
 $migration=Get-Content (Join-Path $root 'database/001-initial.sql') -Raw;$encoded=[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($password));foreach($placeholder in @('__MIGRATION_PASSWORD_B64__','__WORKFLOW_DB_PASSWORD_B64__','__N8N_DB_PASSWORD_B64__')){$migration=$migration.Replace($placeholder,$encoded)}
 Query $migration|Out-Null;Write-Host 'PASS SP3-T6 migration 1'
 Query "SET search_path=salesflow,public;INSERT INTO accounts VALUES('sp3t6',true),('sp3t6-other',true);INSERT INTO controls VALUES('sp3t6','stop','{`"enabled`":false}'),('sp3t6-other','stop','{`"enabled`":false}');SELECT bootstrap('sp3t6-operator','operator','sp3t6-operator','sp3t6');SELECT bootstrap('sp3t6-runtime','runtime','sp3t6-runtime','sp3t6');SELECT bootstrap('sp3t6-other-operator','operator','sp3t6-other-operator','sp3t6-other');"|Out-Null
 foreach($file in Get-ChildItem (Join-Path $root 'config') -Filter *.json|Where-Object Name -ne 'account.json'){$doc=Get-Content $file.FullName -Raw|ConvertFrom-Json;$doc.accountRef='sp3t6';$json=($doc|ConvertTo-Json -Compress -Depth 30).Replace("'","''");$saved=Query "SELECT salesflow.save_config('sp3t6-operator','$json');"|ConvertFrom-Json;Check $saved.created "save $($file.Name)";$activated=Query "SELECT salesflow.activate_config('sp3t6-operator','sp3t6','$($doc.kind)','$($doc.version)',NULL);"|ConvertFrom-Json;Check $activated.activated "activate $($file.Name)"}
 Query (Get-Content (Join-Path $PSScriptRoot 'sp3-t6.sql') -Raw)|ForEach-Object{Write-Host $_}
 Check ((Query "SELECT salesflow.operations('sp3t6-operator',NULL,'{`"action`":`"emergency_stop`",`"enabled`":null}')->>'reason';").Trim()-eq'invalid_input') 'NULL stop input rejected'
 Check ((Query "SELECT salesflow.operations('sp3t6-operator',NULL,'{`"action`":`"activity`",`"cursor`":0}')->>'reason';").Trim()-eq'invalid_input') 'invalid activity cursor rejected'
 Check ((Query "SELECT salesflow.read_activity('sp3t6-operator','sp3t6',NULL)->>'reason';").Trim()-eq'invalid_input') 'direct activity NULL input rejected'
 Check ((Query "SELECT salesflow.read_failures('sp3t6-operator','sp3t6','[]')->>'reason';").Trim()-eq'invalid_input') 'direct failure non-object input rejected'
 Query "INSERT INTO salesflow.audit_events(account_ref,event,reason,actor,details)VALUES('sp3t6','followup_not_scheduled','authority_changed','system',jsonb_build_object('sourceIntentId','11111111-1111-4111-8111-111111111111'));"|Out-Null;$normalized=Query "SELECT salesflow.operations('sp3t6-operator',NULL,'{`"action`":`"activity`",`"limit`":1}');"|ConvertFrom-Json;Check ($normalized.items[0].entityType-eq'intent'-and$normalized.items[0].entityId-eq'11111111-1111-4111-8111-111111111111') 'follow-up scheduling activity is normalized'
 Query "INSERT INTO salesflow.audit_events(account_ref,event,reason,actor,details)VALUES('sp3t6-other','test_activity','created','system','{}');INSERT INTO salesflow.operational_failures(account_ref,source_key,work_type,work_id,state,reason,manual_action_required)VALUES('sp3t6-other','exact-page-failure','message','22222222-2222-4222-8222-222222222222','failed','fixture',true);"|Out-Null;$otherActivityCount=(Query "SELECT count(*)FROM salesflow.audit_events WHERE account_ref='sp3t6-other';").Trim();$exactActivity=Query "SELECT salesflow.read_activity('sp3t6-other-operator','sp3t6-other',jsonb_build_object('limit',$otherActivityCount));"|ConvertFrom-Json;$exactFailures=Query "SELECT salesflow.read_failures('sp3t6-other-operator','sp3t6-other','{`"limit`":1}');"|ConvertFrom-Json;Check ($null-eq$exactActivity.nextCursor-and$null-eq$exactFailures.nextCursor) 'exact-size final pages have no cursor'
 $firstPage=Query "SELECT salesflow.operations('sp3t6-operator',NULL,'{`"action`":`"activity`",`"limit`":1}');"|ConvertFrom-Json;Check ($firstPage.items.Count-eq1-and$null-ne$firstPage.nextCursor) 'activity page returns stable cursor';$secondPage=Query "SELECT salesflow.operations('sp3t6-operator',NULL,jsonb_build_object('action','activity','limit',1,'cursor',$($firstPage.nextCursor)));"|ConvertFrom-Json;Check ($secondPage.items.Count-eq1-and$secondPage.items[0].id-lt$firstPage.items[0].id) 'activity cursor advances newest-first'
 function New-ClaimedWork([string]$suffix){$seed=Query "SELECT salesflow.ingest('sp3t6-runtime',jsonb_build_object('account_ref','sp3t6','provider_id','sp3t6-$suffix-seed','contact_ref','sp3t6-$suffix','body','hello'));"|ConvertFrom-Json;Query "SELECT salesflow.set_consent('sp3t6-runtime','sp3t6','$($seed.contact_id)'::uuid,'granted','synthetic-consent');"|Out-Null;$msg=Query "SELECT salesflow.ingest('sp3t6-runtime',jsonb_build_object('account_ref','sp3t6','provider_id','sp3t6-$suffix-message','contact_ref','sp3t6-$suffix','body','hello'));"|ConvertFrom-Json;$turn=Query "SELECT salesflow.complete_turn('sp3t6-runtime','sp3t6','$($msg.conversation_id)'::uuid);"|ConvertFrom-Json;$claim=Query "SELECT salesflow.claim_dispatch('sp3t6-runtime','sp3t6','$($turn.work_id)'::uuid,clock_timestamp());"|ConvertFrom-Json;Check $claim.ok "$suffix work claimed";return $claim}
 $worker={param($name,$sql)$sql|docker exec -i $name psql -U postgres -v ON_ERROR_STOP=1 -qAt}
 $stopFirst=New-ClaimedWork 'stop-first';$stopJobSql="SET search_path=salesflow,public;BEGIN;SELECT salesflow.operations('sp3t6-operator',NULL,'{`"action`":`"emergency_stop`",`"enabled`":true}');SELECT pg_advisory_xact_lock(hashtextextended('sp3t6-stop-first-ready',0));SELECT pg_sleep(3);COMMIT;";$jobs=@(Start-Job -ScriptBlock $worker -ArgumentList $container,$stopJobSql);$ready=$false;for($n=0;$n-lt20;$n++){if((Query "SELECT NOT pg_try_advisory_xact_lock(hashtextextended('sp3t6-stop-first-ready',0));").Trim()-eq't'){$ready=$true;break};Start-Sleep -Milliseconds 100};Check $ready 'stop-first transaction reached barrier';$blocked=Query "SELECT salesflow.begin_provider_call('sp3t6-runtime','sp3t6','$($stopFirst.work_id)'::uuid,'$($stopFirst.lease)'::uuid);"|ConvertFrom-Json;Check ($blocked.reason-eq'busy') 'stop-first concurrent call waits or returns busy';$jobs|Wait-Job|Receive-Job|Out-Null;$jobs|Remove-Job;$jobs=@();$afterStop=Query "SELECT salesflow.begin_provider_call('sp3t6-runtime','sp3t6','$($stopFirst.work_id)'::uuid,'$($stopFirst.lease)'::uuid);"|ConvertFrom-Json;$blockedCount=(Query "SELECT count(*)FROM salesflow.provider_calls WHERE(account_ref,intent_id)=('sp3t6','$($stopFirst.work_id)'::uuid);").Trim();Check ($afterStop.reason-eq'global_stop'-and$blockedCount-eq'0') 'stop-first commit creates no provider call'
 Query "SELECT salesflow.operations('sp3t6-operator',NULL,'{`"action`":`"emergency_stop`",`"enabled`":false}');"|Out-Null;$callFirst=New-ClaimedWork 'call-first';$later=New-ClaimedWork 'later';$callJobSql="SET search_path=salesflow,public;BEGIN;SELECT salesflow.begin_provider_call('sp3t6-runtime','sp3t6','$($callFirst.work_id)'::uuid,'$($callFirst.lease)'::uuid);SELECT pg_advisory_xact_lock(hashtextextended('sp3t6-call-first-ready',0));SELECT pg_sleep(0.7);COMMIT;";$jobs=@(Start-Job -ScriptBlock $worker -ArgumentList $container,$callJobSql);$ready=$false;for($n=0;$n-lt20;$n++){if((Query "SELECT NOT pg_try_advisory_xact_lock(hashtextextended('sp3t6-call-first-ready',0));").Trim()-eq't'){$ready=$true;break};Start-Sleep -Milliseconds 100};Check $ready 'call-first transaction reached barrier';$stopped=Query "SELECT salesflow.operations('sp3t6-operator',NULL,'{`"action`":`"emergency_stop`",`"enabled`":true}');"|ConvertFrom-Json;$jobs|Wait-Job|Receive-Job|Out-Null;$jobs|Remove-Job;$jobs=@();$replay=Query "SELECT salesflow.begin_provider_call('sp3t6-runtime','sp3t6','$($callFirst.work_id)'::uuid,'$($callFirst.lease)'::uuid);"|ConvertFrom-Json;$laterResult=Query "SELECT salesflow.begin_provider_call('sp3t6-runtime','sp3t6','$($later.work_id)'::uuid,'$($later.lease)'::uuid);"|ConvertFrom-Json;$callCount=(Query "SELECT count(*)FROM salesflow.provider_calls WHERE account_ref='sp3t6'AND intent_id IN('$($callFirst.work_id)'::uuid,'$($later.work_id)'::uuid);").Trim();Check ($stopped.ok-and$replay.terminal-eq'already_started'-and$laterResult.reason-eq'global_stop'-and$callCount-eq'1') 'call-first commit preserves one started call and blocks later starts'
 $jobSql="SET search_path=salesflow,public;BEGIN;SELECT pg_advisory_xact_lock(hashtextextended('sp3t6:control:stop',0));SELECT pg_advisory_xact_lock(hashtextextended('sp3t6-busy-stop-ready',0));SELECT pg_sleep(3);COMMIT;";$jobs=@(Start-Job -ScriptBlock $worker -ArgumentList $container,$jobSql);$ready=$false;for($n=0;$n-lt20;$n++){if((Query "SELECT NOT pg_try_advisory_xact_lock(hashtextextended('sp3t6-busy-stop-ready',0));").Trim()-eq't'){$ready=$true;break};Start-Sleep -Milliseconds 100};Check $ready 'busy-stop transaction reached barrier';$busy=Query "SELECT salesflow.operations('sp3t6-operator',NULL,'{`"action`":`"emergency_stop`",`"enabled`":false}');"|ConvertFrom-Json;Check ($busy.reason-eq'busy') 'busy stop is not reported as accepted';$jobs|Wait-Job|Receive-Job|Out-Null;$jobs|Remove-Job;$jobs=@();$stillStopped=(Query "SELECT value->>'enabled'FROM salesflow.controls WHERE(account_ref,key)=('sp3t6','stop');").Trim();Check ($stillStopped-eq'true') 'busy stop leaves state unchanged'
 $finished=Query "SELECT salesflow.finish_dispatch('sp3t6-runtime','sp3t6','$($callFirst.work_id)'::uuid,'$($callFirst.lease)'::uuid,'success');"|ConvertFrom-Json;Check ($finished.terminal-eq'sent') 'call-first started call completes';$callback=Query "SELECT salesflow.callback('sp3t6-runtime',jsonb_build_object('account_ref','sp3t6','event_id','sp3t6-sent-failed','provider_id','$($replay.provider_id)','status','failed','provider_time',clock_timestamp()));"|ConvertFrom-Json;$callbackFailure=Query "SELECT state||':'||reason||':'||(occurred_at IS NOT NULL)FROM salesflow.operational_failures WHERE account_ref='sp3t6'AND source_key='provider-event:sp3t6-sent-failed';";Check ($callback.status-eq'failed'-and$callbackFailure.Trim()-eq'failed:provider_failed:true') 'sent callback failure is visible'
 Query "SELECT salesflow.operations('sp3t6-operator',NULL,'{`"action`":`"emergency_stop`",`"enabled`":false}');"|Out-Null;$stale=New-ClaimedWork 'stale-callback';$staleStart=Query "SELECT salesflow.begin_provider_call('sp3t6-runtime','sp3t6','$($stale.work_id)'::uuid,'$($stale.lease)'::uuid);"|ConvertFrom-Json;Query "SELECT salesflow.finish_dispatch('sp3t6-runtime','sp3t6','$($stale.work_id)'::uuid,'$($stale.lease)'::uuid,'success');"|Out-Null;Query "SELECT salesflow.callback('sp3t6-runtime',jsonb_build_object('account_ref','sp3t6','event_id','sp3t6-delivered-new','provider_id','$($staleStart.provider_id)','status','delivered','provider_time',clock_timestamp()));"|Out-Null;Query "SELECT salesflow.callback('sp3t6-runtime',jsonb_build_object('account_ref','sp3t6','event_id','sp3t6-failed-stale','provider_id','$($staleStart.provider_id)','status','failed','provider_time',clock_timestamp()-interval'1 hour'));"|Out-Null;$staleProof=Query "SELECT(SELECT state FROM salesflow.intents WHERE(account_ref,id)=('sp3t6','$($stale.work_id)'::uuid))||':'||(SELECT count(*)FROM salesflow.operational_failures WHERE account_ref='sp3t6'AND source_key='provider-event:sp3t6-failed-stale');";Check ($staleProof.Trim()-eq'sent:0') 'stale failed callback creates no false failure'
 $parentId=Query "SET search_path=salesflow,public;WITH c AS(INSERT INTO contacts(account_ref)VALUES('sp3t6')RETURNING id),v AS(INSERT INTO conversations(account_ref,contact_id)SELECT'sp3t6',id FROM c RETURNING id,contact_id)INSERT INTO followups(account_ref,contact_id,conversation_id,due_at,expected_version,state,attempts,next_attempt)SELECT'sp3t6',contact_id,id,clock_timestamp(),0,'retry',3,clock_timestamp()FROM v RETURNING id;";Query "SET search_path=salesflow,public;INSERT INTO followup_transitions(account_ref,followup_id,event_key,from_state,to_state,reason)VALUES('sp3t6','$($parentId.Trim())'::uuid,'parent-exhausted','retry','exhausted','retry_exhausted');"|Out-Null;$parentFailure=Query "SELECT state||':'||reason FROM salesflow.operational_failures WHERE account_ref='sp3t6'AND source_key LIKE'followup-transition:%'AND work_id='$($parentId.Trim())'::uuid;";Check ($parentFailure.Trim()-eq'exhausted:retry_exhausted') 'parent-only follow-up exhaustion is visible'
 $handoffEvidence=Query "SET search_path=salesflow,public;WITH source AS(SELECT account_ref,contact_id,conversation_id,source_id FROM intents WHERE(account_ref,id)=('sp3t6','$($callFirst.work_id)'::uuid)),created AS(INSERT INTO handoffs(account_ref,contact_id,conversation_id,source_id,reason,queue,deadline,evidence,state,attempts)SELECT account_ref,contact_id,conversation_id,source_id,'human_requested','ops',clock_timestamp()+interval'1 hour','{}','pending',1 FROM source RETURNING*)UPDATE conversations v SET lifecycle='opted_out'FROM created h WHERE(v.account_ref,v.id)=(h.account_ref,h.conversation_id)RETURNING h.id;";$handoffId=$handoffEvidence.Trim();Query "SET search_path=salesflow,public;UPDATE handoffs SET state='suppressed'WHERE(account_ref,id)=('sp3t6','$handoffId'::uuid);INSERT INTO handoff_notification_events(account_ref,handoff_id,attempt_no,outcome,result)VALUES('sp3t6','$handoffId'::uuid,1,'success','authority_changed');"|Out-Null;$handoffBefore=(Query "SELECT count(*)FROM salesflow.audit_events WHERE account_ref='sp3t6'AND event='handoff_changed'AND details->>'entityId'='$handoffId';").Trim();Query "UPDATE salesflow.handoffs SET state=state WHERE(account_ref,id)=('sp3t6','$handoffId'::uuid);"|Out-Null;$handoffProof=Query "SELECT COALESCE((SELECT reason FROM salesflow.operational_failures WHERE account_ref='sp3t6'AND work_id='$handoffId'::uuid AND work_type='handoff'ORDER BY id DESC LIMIT 1),'missing')||':'||COALESCE((SELECT reason FROM salesflow.audit_events WHERE account_ref='sp3t6'AND event='handoff_changed'AND details->>'entityId'='$handoffId'ORDER BY id DESC LIMIT 1),'missing')||':'||COALESCE((SELECT failure_reason FROM salesflow.handoff_notification_events WHERE(account_ref,handoff_id)=('sp3t6','$handoffId'::uuid)ORDER BY attempt_no DESC LIMIT 1),'missing')||':'||(SELECT count(*)FROM salesflow.audit_events WHERE account_ref='sp3t6'AND event='handoff_changed'AND details->>'entityId'='$handoffId');";Check ($handoffProof.Trim()-eq"opted_out:suppressed:opted_out:$handoffBefore") "handoff failure reason persists and no-op update is silent: $($handoffProof.Trim())"
 $disableFirst=Query "SELECT salesflow.set_account_enabled('sp3t6-other-operator','sp3t6-other',false);"|ConvertFrom-Json;$disableReplay=Query "SELECT salesflow.set_account_enabled('sp3t6-other-operator','sp3t6-other',false);"|ConvertFrom-Json;$accountActivity=Query "SELECT count(*)||':'||min(details->>'previousEnabled')||':'||min(details->>'enabled')FROM salesflow.audit_events WHERE account_ref='sp3t6-other'AND event='account_enabled_changed';";Check ($disableFirst.changed-and-not$disableReplay.changed-and$accountActivity.Trim()-eq'1:true:false') 'account enable change records before/after once'
 Query $migration|Out-Null;$retainedHandoffSource="handoff-attempt:${handoffId}:1";Query "SET search_path=salesflow,public;ALTER TABLE operational_failures DISABLE TRIGGER operational_failures_immutable;UPDATE operational_failures SET at=clock_timestamp()-interval'4000 days'WHERE(account_ref,source_key)=('sp3t6','$retainedHandoffSource');ALTER TABLE operational_failures ENABLE TRIGGER operational_failures_immutable;"|Out-Null
 Query "SET search_path=salesflow,public;INSERT INTO operational_failures(account_ref,source_key,work_type,work_id,state,reason,manual_action_required,at)VALUES('sp3t6','retention-fixture','message',gen_random_uuid(),'failed','old_failure',true,clock_timestamp()-interval'4000 days');ALTER TABLE intent_transitions DISABLE TRIGGER intent_activity_capture;INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason,at)VALUES('sp3t6','$($callFirst.work_id)'::uuid,'sent','failed','retention-backfill-fixture',clock_timestamp()-interval'4000 days');ALTER TABLE intent_transitions ENABLE TRIGGER intent_activity_capture;"|Out-Null;Query $migration|Out-Null;$expiredBackfill=Query "SELECT(SELECT count(*)FROM salesflow.audit_events WHERE account_ref='sp3t6'AND reason='retention-backfill-fixture')||':'||(SELECT count(*)FROM salesflow.operational_failures WHERE account_ref='sp3t6'AND source_key LIKE'legacy-intent:%'AND work_id='$($callFirst.work_id)'::uuid)||':'||(SELECT count(*)FROM salesflow.activity_backfill_markers WHERE account_ref='sp3t6'AND source_key LIKE'intent-transition:%')||':'||(SELECT count(*)FROM salesflow.failure_backfill_markers WHERE account_ref='sp3t6'AND source_key LIKE'legacy-intent:%');";$retained=Query "SELECT salesflow.enforce_retention('sp3t6-operator','sp3t6',clock_timestamp());"|ConvertFrom-Json;Query $migration|Out-Null;$backfillAfter=Query "SELECT(SELECT count(*)FROM salesflow.audit_events WHERE account_ref='sp3t6'AND reason='retention-backfill-fixture')||':'||(SELECT count(*)FROM salesflow.operational_failures WHERE account_ref='sp3t6'AND source_key='retention-fixture')||':'||(SELECT count(*)FROM salesflow.activity_backfill_markers WHERE account_ref='sp3t6'AND source_key LIKE'intent-transition:%')||':'||(SELECT count(*)FROM salesflow.failure_backfill_markers WHERE account_ref='sp3t6'AND source_key LIKE'legacy-intent:%');";Check ($expiredBackfill.Trim()-match'^0:0:[1-9][0-9]*:[1-9][0-9]*$'-and$retained.ok-and$retained.failurePurged-ge1-and$backfillAfter.Trim()-match'^0:0:[1-9][0-9]*:[1-9][0-9]*$') 'expired first backfill is skipped and retention purge survives migration replay'
 $handoffReplayProof=Query "SELECT(SELECT count(*)FROM salesflow.operational_failures WHERE(account_ref,source_key)=('sp3t6','$retainedHandoffSource'))||':'||(SELECT count(*)FROM salesflow.failure_backfill_markers WHERE(account_ref,source_key)=('sp3t6','$retainedHandoffSource'));";Check ($handoffReplayProof.Trim()-eq'0:1') "retained-away Handoff failure is not recreated by migration replay: $($handoffReplayProof.Trim())"
 $immutable=$false;try{Query "UPDATE salesflow.audit_events SET actor='changed'WHERE id=(SELECT max(id)FROM salesflow.audit_events);"|Out-Null}catch{$immutable=$true};Check $immutable 'activity evidence is append-only'
 Query "SELECT salesflow.operations('sp3t6-operator',NULL,'{`"action`":`"emergency_stop`",`"enabled`":false}');"|Out-Null;$legacy=New-ClaimedWork 'legacy-time';Query "SET search_path=salesflow,public;UPDATE intents SET state='retry',reason='pre_call_retryable',lease=NULL,lease_until=NULL,provider_time=NULL WHERE(account_ref,id)=('sp3t6','$($legacy.work_id)'::uuid);ALTER TABLE intent_transitions DISABLE TRIGGER intent_activity_capture;INSERT INTO intent_transitions(account_ref,intent_id,from_state,to_state,reason)VALUES('sp3t6','$($legacy.work_id)'::uuid,'leased','retry','pre_call_retryable');ALTER TABLE intent_transitions ENABLE TRIGGER intent_activity_capture;"|Out-Null;$legacyHandoff=Query "SET search_path=salesflow,public;ALTER TABLE handoffs DISABLE TRIGGER handoff_activity_insert_capture;WITH source AS(SELECT account_ref,contact_id,conversation_id,source_id FROM intents WHERE(account_ref,id)=('sp3t6','$($legacy.work_id)'::uuid))INSERT INTO handoffs(account_ref,contact_id,conversation_id,source_id,reason,queue,deadline,evidence,state)SELECT account_ref,contact_id,conversation_id,source_id,'human_requested','ops',clock_timestamp()+interval'1 hour','{}','pending'FROM source RETURNING id;ALTER TABLE handoffs ENABLE TRIGGER handoff_activity_insert_capture;";$legacyHandoffId=$legacyHandoff.Trim();Query $migration|Out-Null;Query $migration|Out-Null;$legacyProof=Query "SELECT(SELECT occurred_at IS NULL AND at IS NOT NULL FROM salesflow.operational_failures WHERE account_ref='sp3t6'AND source_key='legacy-intent:$($legacy.work_id):retry')::text||':'||(SELECT count(*)FROM salesflow.operational_failures WHERE account_ref='sp3t6'AND work_id='$($legacy.work_id)'::uuid AND state='retry'AND reason='pre_call_retryable')||':'||(SELECT count(*)FROM salesflow.audit_events WHERE account_ref='sp3t6'AND event='message_send_transition'AND details->>'entityId'='$($legacy.work_id)'AND details->>'migrationKey'IS NOT NULL)||':'||(SELECT count(*)FROM salesflow.audit_events WHERE account_ref='sp3t6'AND event='handoff_migration_observed'AND details->>'entityId'='$legacyHandoffId');";Check ($legacyProof.Trim()-eq'true:1:1:1') 'legacy failure and material activity backfills are idempotent';Write-Host 'PASS SP3-T6 migration repeated'
 $workflow=Get-Content (Join-Path $root 'workflows/07-error-and-operations.json') -Raw|ConvertFrom-Json;$node=$workflow.nodes|Where-Object{$_.name-eq'Account Bound Stop Activity and Failure Operations'};Check ($node.parameters.query-match'operations\(\$1,NULL,\$2::jsonb\)') 'Workflow 07 routes account-bound operations';Check ($node.parameters.query-match"'busy' THEN 503") 'Workflow 07 maps busy without claiming success'
 Write-Host 'PASS SP3-T6 FULL PASS'
}finally{foreach($job in $jobs){if($job.State-eq'Running'){$job|Stop-Job};$job|Remove-Job -Force -ErrorAction SilentlyContinue};if($launched){docker rm --force --volumes $container *> $null;Check ($LASTEXITCODE-eq0) 'disposable container and volumes removed'}}
